import {randomUUID} from 'node:crypto';
import {syntheticBookingRequest} from './confirmed-booking.ts';
export function confirmedJobRecords(){
 const q=syntheticBookingRequest(),stamp=new Date().toISOString().replace(/\.(\d{3})Z$/,'.$1000Z'),actor=q.payload.operatorId,appointmentId=randomUUID(),shared={business_id:q.businessId,created_at:stamp,created_by:actor,operation_id:q.operationId,origin:'manual'};
 const job={id:q.jobId,...shared,customer_id:q.payload.customerId,operator_actor_id:actor,fulfillment_mode:'mobile',mode_version_id:randomUUID(),work_address_id:null,work_location_snapshot:q.payload.workLocation,state:'scheduled',current_appointment_id:appointmentId,first_work_at:null,completed_at:null,completion_outcome:null,version:'1',updated_at:stamp,updated_by:actor};
 const appointment={id:appointmentId,...shared,job_id:q.jobId,sequence:'1',replaces_id:null,...q.payload.appointment,confirmation_state:'confirmed',reason:null};
 const draft={schemaVersion:1,kind:'appointment_confirmation',state:'prepared',businessId:q.businessId,jobId:q.jobId,appointmentId,confirmationState:'confirmed',customerId:q.payload.customerId,customerName:'Synthetic customer',fulfillmentMode:'mobile',workLocation:q.payload.workLocation,startAt:appointment.start_at,endAt:appointment.end_at,timezone:'UTC',vehicles:[{vehicleId:q.payload.vehicles[0]!.vehicleId,label:'Synthetic sedan'}],scope:[{sourceAllocationId:q.payload.allocationPlans[0]!.sourceAllocationId,partitionId:q.payload.allocationPlans[0]!.parts[0]!.partitionId,scopeDescription:'Synthetic scope',amountCents:'25000'}],bodyText:'Prepared synthetic appointment confirmation'};
 const head={schemaVersion:1,businessId:q.businessId,job,appointment,latestAppointment:structuredClone(appointment),confirmationDraft:draft,vehicleCount:1,encounterCount:1,allocationCount:1};
 const summary={jobId:q.jobId,version:'1',state:'scheduled',customerId:job.customer_id,customerName:'Synthetic customer',operatorId:actor,fulfillmentMode:'mobile',appointmentId,appointmentSequence:'1',startAt:appointment.start_at,endAt:appointment.end_at,timezone:'UTC',confirmationState:'confirmed',unknownTravel:false,workLocation:q.payload.workLocation,vehicleCount:1,pendingAppointment:null,vehicleLabels:['Synthetic sedan']};
 const event={id:randomUUID(),sequence:'1',operationId:q.operationId,actorId:actor,recordedAt:stamp,effectiveAt:stamp,fromState:null,toState:'scheduled',reason:null,action:'book',appointment,draft:{state:'prepared',appointmentId,confirmationState:'confirmed',bodyText:draft.bodyText},customerCommunication:null};
 return {q,head,summary,event};
}
